  {
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "What is construction robotics data collection?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "It's the capture of real jobsite data that trains construction robots, including LiDAR and camera scans, teleoperated trade demonstrations, and aerial surveys, recorded across build phases so models stay reliable as the site changes."
        }
      },
      {
        "@type": "Question",
        "name": "Can you collect data on an active construction site?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes, under the project's safety plan and with the general contractor's approval. We schedule around trades and capture with survey control so data can be registered to the design model."
        }
      },
      {
        "@type": "Question",
        "name": "How do you handle constant change on a jobsite?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Every recording is tied to the project phase and location, and scans are registered to BIM. That lets teams know exactly which version of the site the data represents and when it needs refreshing."
        }
      },
      {
        "@type": "Question",
        "name": "Do you capture drone data for construction progress?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Yes. Aerial surveys are planned around the resolution the model needs and combined with ground scans for interior progress."
        }
      },
      {
        "@type": "Question",
        "name": "How do robots localize indoors without GPS?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Localization relies on LiDAR, cameras, and known reference points. We capture with survey control points so localization models can be trained and verified inside the structure."
        }
      },
      {
        "@type": "Question",
        "name": "What labels do construction datasets need?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "Common labels include as-built elements, deviations from design, embeds, work zones, and task outcomes. Our annotation team labels against the same phase and BIM references used in capture."
        }
      }
    ]
  }
